"""Original respiratory failure chapter: gas exchange and ventilatory support."""
from qbank_authoring import question,ref,finalize
NV=ref('BTS/ICS: Ventilatory Management of Acute Hypercapnic Respiratory Failure','https://thorax.bmj.com/content/71/Suppl_2/ii1')
OX=ref('BTS: Oxygen Use in Adults in Healthcare and Emergency Settings','https://doi.org/10.1136/THORAXJNL-2016-209729')
NS=ref('ATS: Noninvasive Respiratory Support in Adult Acute Respiratory Failure, 2026','https://academic.oup.com/ajrccm/article/212/9/2135/8721554')
rows=[]
def q(*a,**k):rows.append(question(*a,**k))
q('An adult has room-air PaO2 52 mmHg and PaCO2 31 mmHg during acute pneumonia. Which gas-exchange pattern is present?', 'Predominantly hypoxemic respiratory failure',[
 ('Predominantly hypercapnic ventilatory failure','PaCO2 is reduced, not elevated.'),('Normal oxygenation because CO2 is low','A low CO2 does not negate the severe oxygen deficit.'),('A pure metabolic disorder established without acid-base assessment','The stated gases directly establish significant hypoxemia.')],
 'Classify oxygenation and ventilation separately', '**Hypoxemia can coexist with normal or low PaCO2.**',['Tachypnea may maintain or lower arterial CO2.','Pneumonia commonly impairs ventilation-perfusion matching and creates shunt.'], '**Treat the cause and support oxygenation.**',['Assess work of breathing and trajectory, not just one number.','Rising CO2 during deterioration can indicate developing fatigue.'],[['PaO2','Low'],['PaCO2','Low in this case'],['Pattern','Hypoxemic failure']],[OX,NS],style='clinical_scenario')
q('A blood gas shows pH 7.24, PaCO2 70 mmHg and bicarbonate 29 mmol/L. Which primary disorder is present?', 'Respiratory acidosis with incomplete compensation',[
 ('Primary respiratory alkalosis','CO2 is high with acidemia.'),('Primary metabolic alkalosis as the sole disorder','Alkalosis does not explain the acidemia and marked hypercapnia.'),('A fully compensated chronic respiratory acidosis','The pH is substantially acidemic.')],
 'Read the pH and the direction of CO2 together', '**Acidemia with elevated CO2 establishes a respiratory acidifying process.**',['The bicarbonate indicates some buffering or chronic component.','A mixed disorder requires comparison with expected compensation and clinical context.'], '**Assess ventilatory support needs promptly.**',['Hypercapnic failure can worsen rapidly.','Treat the precipitating airway, neuromuscular, drug or chest-wall process.'],[['pH','Acidemia'],['PaCO2','Respiratory acidifying direction'],['Bicarbonate','Does not fully normalize pH']],[NV],style='clinical_scenario')
q('At a fixed rate of CO2 production, what happens to PaCO2 when effective alveolar ventilation falls?', 'PaCO2 rises',[
 ('PaCO2 necessarily falls','The relationship is inverse, not direct in that direction.'),('PaCO2 is determined only by inspired oxygen concentration','Ventilation is central to CO2 clearance.'),('PaCO2 is independent of dead-space ventilation','Dead space changes effective alveolar ventilation for a given minute volume.')],
 'Minute ventilation and alveolar ventilation are not interchangeable', '**Alveolar ventilation is the part that participates effectively in gas exchange.**',['Increasing dead-space fraction can impair CO2 clearance despite a large total minute volume.','Respiratory muscle failure can reduce effective ventilation.'], '**Treat the mechanism of hypoventilation.**',['Oxygen alone does not restore CO2 clearance.','Adjust support while monitoring pH, CO2 and the patient’s work of breathing.'],[['Lower alveolar ventilation','Higher PaCO2'],['Higher dead space','Less effective ventilation'],['Oxygen','Treats oxygen deficit, not the ventilation mechanism']],[NV,OX])
q('Which mechanism typically causes hypoxemia that responds poorly to a high inspired oxygen concentration?', 'A substantial right-to-left intrapulmonary shunt',[
 ('Pure alveolar hypoventilation without parenchymal disease','Its oxygen deficit generally improves with supplemental oxygen while ventilation still needs correction.'),('Low inspired oxygen at altitude alone','Increasing inspired oxygen usually corrects that mechanism.'),('Mild diffusion limitation alone','Supplemental oxygen generally improves the gradient and oxygenation.')],
 'Blood bypassing ventilated alveoli limits oxygen response', '**Shunted blood does not fully contact alveolar oxygen.**',['Consolidation and flooded alveoli can create shunt.','Mixed mechanisms are common in acute lung disease.'], '**Use oxygen response as one physiological clue.**',['Recruitment with appropriate pressure may help selected lung units.','Persistent hypoxemia requires assessment of the disease and support strategy.'],[['Shunt','Relatively poor oxygen response'],['Low inspired oxygen','Usually responds to higher FiO2'],['Hypoventilation','Oxygen helps PaO2 but ventilation must be corrected']],[NS,OX])
q('A patient with opioid-induced hypoventilation has hypoxemia and hypercapnia but no parenchymal lung disease. Which A–a oxygen-gradient pattern is expected in a pure process?', 'A relatively normal A–a gradient',[
 ('A markedly widened gradient is required in pure hypoventilation','Pure hypoventilation reduces alveolar and arterial oxygen together.'),('An A–a gradient proves the opioid concentration','It is a gas-exchange calculation, not a drug assay.'),('The gradient cannot be interpreted with an ABG and inspired oxygen information','Those are central inputs to its estimation.')],
 'The A–a gradient helps separate low alveolar oxygen from transfer abnormalities', '**Pure hypoventilation can lower PaO2 without markedly widening the gradient.**',['Aspiration or another coexisting lung process can widen it.','Age and inspired oxygen affect interpretation.'], '**Treat airway and ventilatory failure urgently.**',['Use an appropriate reversal strategy and support when indicated.','Do not let an explanatory gradient delay resuscitation.'],[['Pure hypoventilation','Often normal gradient'],['Shunt / VQ mismatch','Usually widened gradient'],['Mixed disease','Can alter the expected pattern']],[OX,NV],style='clinical_scenario')
q('On room air at sea level, assume barometric pressure 760 mmHg, water vapor pressure 47 mmHg and respiratory quotient 0.8. If PaCO2 is 40, approximately what is alveolar PO2?', '100 mmHg',[
 ('150 mmHg','That approximates inspired humidified oxygen before subtracting the CO2 term.'),('40 mmHg','That is the arterial CO2 value, not alveolar oxygen.'),('200 mmHg','This is not the result of the stated alveolar gas equation.')],
 'Use the simplified alveolar gas equation with stated assumptions', '**PAO2 ≈ FiO2 × (PB − PH2O) − PaCO2/R.**',['0.21 × 713 is about 150.','Subtract 40/0.8 = 50 to obtain about 100.'], '**Then compare with arterial oxygen if calculating the A–a gradient.**',['The assumptions change at altitude or with a different FiO2.','This calculation does not independently identify the cause of respiratory failure.'],[['Inspired term','About 150 mmHg'],['CO2 correction','50 mmHg'],['Alveolar PO2','About 100 mmHg']],[OX])
q('An at-risk hypercapnic patient is receiving acute oxygen while ABG assessment is arranged. Which target is generally appropriate under BTS guidance?', 'SpO2 88–92%',[
 ('SpO2 100% in every case regardless of CO2 or pH','Uncontrolled excess oxygen can worsen hypercapnia in susceptible patients.'),('Withhold oxygen despite severe hypoxemia','Hypoxemia still requires treatment.'),('SpO2 below 80% as a routine target','That permits dangerous hypoxemia.')],
 'Controlled oxygen balances two clinical hazards', '**Treat hypoxemia while avoiding unnecessary hyperoxia in susceptible patients.**',['Obtain blood gases and reassess after treatment changes.','The target can be individualized from prior information and the current gas results.'], '**Support ventilation when oxygen alone is insufficient.**',['Acidosis and respiratory effort inform NIV or intubation decisions.','Do not abruptly stop necessary oxygen to correct CO2 without managing the patient.'],[['Initial at-risk target','88–92%'],['Monitoring','ABG and clinical response'],['Ventilatory failure','May require assisted ventilation']],[OX,NV])
q('A COPD exacerbation remains acidotic with pH 7.28 and PaCO2 68 mmHg after initial medical treatment. The patient is alert, cooperative and protecting the airway. Which support is appropriate?', 'A monitored trial of bilevel noninvasive ventilation with a defined escalation plan',[
 ('Oxygen alone indefinitely despite persistent acidosis','This does not adequately address the ventilatory failure.'),('Immediate discharge because the patient is alert','Persistent respiratory acidosis requires monitored treatment.'),('Sedation to suppress respiratory effort without ventilatory support','This risks worsening ventilation.')],
 'NIV can unload respiratory muscles and improve alveolar ventilation', '**Persistent hypercapnic acidosis in an appropriate COPD patient is a strong NIV indication.**',['Treat the exacerbation simultaneously.','Check gases before and after initiation.'], '**Prepare for failure before starting.**',['Monitor pH, respiratory rate, consciousness and gas exchange.','Do not delay intubation when deterioration makes it necessary.'],[['Eligibility','Acidosis plus suitable airway and cooperation'],['Goal','Improve ventilation and reduce work'],['Safety','Close monitoring and escalation']],[NV,NS],style='clinical_scenario')
q('During NIV, a patient becomes obtunded, cannot clear secretions and has worsening acidemia. What is the best next step?', 'Urgent airway and invasive-ventilation assessment rather than persisting with failing NIV',[
 ('Continue the same NIV settings without reassessment','Deterioration and airway failure are dangerous.'),('Increase sedation solely to improve mask tolerance','This can further impair airway protection and ventilation.'),('Wait until oxygen saturation becomes unrecordable','Escalation should precede catastrophic deterioration.')],
 'NIV success depends on airway safety as well as gas exchange', '**An unprotected airway and worsening physiology require urgent escalation.**',['Evaluate reversible interface or setting problems quickly.','Do not let troubleshooting postpone necessary intubation.'], '**Honor the patient’s agreed ceiling of care.**',['The escalation plan should be documented early.','If invasive support is not consistent with goals, provide an appropriate alternative treatment and symptom plan.'],[['Deterioration','Reassess immediately'],['Airway failure','NIV may be unsafe'],['Plan','Escalate according to goals and urgency']],[NV,NS],style='clinical_scenario')
q('On bilevel NIV, which change primarily increases pressure support and can improve ventilation if other factors are suitable?', 'Increase inspiratory pressure while keeping expiratory pressure unchanged',[
 ('Raise inspiratory and expiratory pressures equally and assume pressure support rises','The difference between the pressures remains unchanged.'),('Reduce inspiratory pressure below expiratory pressure','That does not provide the intended inspiratory assistance.'),('Increase oxygen concentration alone','Oxygen concentration does not directly increase pressure support.')],
 'Pressure support is the inspiratory–expiratory pressure difference', '**The difference between IPAP and EPAP contributes to inspiratory assistance.**',['Tidal volume also depends on mechanics, effort and leak.','EPAP has separate effects on recruitment and airway patency.'], '**Titrate to the patient and the measured response.**',['Check comfort, leak and synchrony.','Avoid treating a numerical setting as a guarantee of adequate ventilation.'],[['IPAP − EPAP','Pressure support'],['Higher IPAP with fixed EPAP','Greater pressure difference'],['FiO2','Oxygenation rather than pressure support']],[NV])
q('A patient on NIV has poor CO2 clearance and a large mask leak. Which response is most appropriate first?', 'Assess interface fit, circuit integrity and synchrony before assuming the disease is refractory',[
 ('Ignore leak because displayed pressures guarantee alveolar ventilation','Leak can compromise effective support and triggering.'),('Increase oxygen alone as the specific correction for leak','It does not correct poor delivery of pressure support.'),('Remove all monitoring while changing settings','Reassessment is essential during adjustments.')],
 'Delivery failure can mimic biological treatment failure', '**Effective NIV depends on a functioning interface and circuit.**',['Leaks affect triggering, cycling and delivered ventilation.','Comfort and skin injury also influence adherence.'], '**Correct remediable problems while watching for deterioration.**',['Review settings and the patient’s effort.','If physiology remains poor, escalate rather than repeatedly adjusting a failing approach.'],[['Leak','May reduce effective assistance'],['Assessment','Interface, circuit and synchrony'],['Reassessment','ABG and clinical response']],[NV],style='clinical_scenario')
q('Which presentation favors ventilatory support rather than supplemental oxygen as the sole respiratory intervention?', 'Progressive neuromuscular weakness with falling vital capacity and rising PaCO2',[
 ('A stable mild isolated oxygen deficit without ventilatory failure','Oxygen may be sufficient while the cause is addressed.'),('A low pulse-oximeter reading caused by a displaced sensor alone','First correct and verify the measurement.'),('Normal ventilation and oxygenation in an asymptomatic adult','No support is indicated solely by that description.')],
 'Respiratory muscle failure is a pump problem', '**Oxygen cannot substitute for adequate ventilation.**',['Bulbar function and secretion clearance influence the safest support mode.','CO2 elevation may be a late sign in rapidly progressive weakness.'], '**Monitor trajectory and airway safety.**',['Serial respiratory mechanics and clinical assessment matter.','Use disease-specific thresholds and early critical-care involvement.'],[['Weak pump','Ventilation support may be needed'],['Bulbar dysfunction','Airway protection concern'],['Oxygen alone','Can mask deterioration without fixing ventilation']],[NV],style='clinical_scenario')
q('Which mechanism contributes to the benefit of high-flow nasal oxygen in acute hypoxemic respiratory failure?', 'Delivery of warmed humidified gas at high flow with a more reliable FiO2 and upper-airway dead-space washout',[
 ('Guaranteed fixed high-level PEEP equal to invasive ventilation','Pressure depends on flow and airway conditions and is not a fixed equivalent.'),('Direct paralysis of respiratory muscles','HFNO does not provide neuromuscular blockade.'),('Elimination of the need to assess work of breathing','Patients can deteriorate despite acceptable oxygen saturation.')],
 'HFNO supports oxygenation but does not secure an airway', '**High flow can better meet inspiratory demand and improve comfort.**',['Some distending pressure and dead-space washout may contribute.','The physiological effect varies with mouth opening and other factors.'], '**Monitor for treatment failure.**',['Persistent distress, deteriorating gas exchange or altered consciousness requires escalation assessment.','Avoid delaying intubation because the device is comfortable.'],[['Main effects','Stable oxygen delivery and washout'],['Limit','No protected airway'],['Safety','Trajectory and work-of-breathing monitoring']],[NS])
q('A patient on high-flow oxygen maintains SpO2 95% but has rapidly increasing respiratory effort, exhaustion and altered mentation. Which interpretation is best?', 'The respiratory support may be failing despite an acceptable saturation',[
 ('Normal saturation proves adequate ventilation and safe work of breathing','Oxygenation is only one component of respiratory status.'),('Increasing respiratory effort is always a favorable response','It can indicate impending fatigue.'),('Intubation assessment should wait until saturation falls below 50%','That delay risks a peri-arrest airway emergency.')],
 'A saturation number cannot capture the whole respiratory state', '**Work of breathing and consciousness are critical failure signals.**',['High inspired oxygen may preserve saturation temporarily.','CO2 retention or fatigue can evolve.'], '**Arrange urgent expert reassessment and escalation when indicated.**',['Review the cause and airway plan.','Do not rely on a single score or device setting to override clinical deterioration.'],[['Oxygenation','May look acceptable temporarily'],['Effort / mentation','Important danger signals'],['Action','Urgent reassessment and possible escalation']],[NS],style='clinical_scenario')
q('Which statement about oxygen delivery devices is correct?', 'A Venturi system can provide a more controlled inspired oxygen concentration when used with the specified flow and setup',[
 ('A nasal cannula always gives an exact FiO2 independent of breathing pattern','Delivered concentration varies with demand and ventilation.'),('A reservoir mask guarantees adequate ventilation in apnea','It supplies oxygen but does not ventilate an apneic patient.'),('The same flow gives identical FiO2 through every device','Device design and patient factors matter.')],
 'Match the delivery system to the physiological goal', '**Controlled oxygen is useful when precision is important.**',['Use the manufacturer-specified flow for the Venturi adapter.','Verify the patient’s achieved saturation and gas response.'], '**A device is not a substitute for reassessment.**',['Changing respiratory demand can alter effectiveness.','Apnea or severe pump failure requires ventilation support.'],[['Venturi','Controlled-concentration strategy'],['Nasal cannula','Variable effective FiO2'],['Reservoir mask','Oxygen delivery, not ventilation']],[OX])
q('A patient has PaCO2 60 mmHg, bicarbonate 34 mmol/L and near-normal pH before an acute illness. Which pattern is most likely?', 'Chronic hypercapnia with renal compensation',[
 ('Pure acute respiratory acidosis without compensation','The high bicarbonate and near-normal pH suggest a chronic component.'),('Primary respiratory alkalosis','CO2 is elevated rather than reduced.'),('Normal ventilation because pH is near normal','Compensation can normalize pH while ventilation remains abnormal.')],
 'A normal-looking pH can conceal a chronic respiratory disorder', '**Renal bicarbonate retention buffers sustained CO2 elevation.**',['The time course and expected compensation need clinical correlation.','A superimposed acute insult can produce acute-on-chronic acidosis.'], '**Use prior gases when available.**',['Do not force CO2 to normal abruptly without considering the chronic state and overall physiology.','Treat the precipitant and titrate support to appropriate clinical goals.'],[['CO2','Chronically elevated'],['Bicarbonate','Renal compensation'],['pH','May approach normal despite abnormal ventilation']],[NV],style='clinical_scenario')
q('In acute cardiogenic pulmonary edema with respiratory distress and an appropriate airway, which support can improve oxygenation and reduce work of breathing?', 'CPAP or suitable bilevel NIV alongside treatment of the cardiac cause',[
 ('Antibiotics as the sole immediate treatment without infection evidence','They do not directly address cardiogenic edema.'),('No respiratory support until diuresis is complete','Severe distress may need immediate support.'),('CPAP as a replacement for all hemodynamic assessment','Hypotension and other contraindications still matter.')],
 'Positive pressure can help the flooded, distressed cardiogenic lung', '**Noninvasive support is an established option in suitable acute pulmonary edema.**',['It may improve oxygenation and respiratory mechanics.','Bilevel assistance can add ventilation support when needed.'], '**Treat the hemodynamic cause simultaneously.**',['Consider blood pressure, ischemia, congestion and valve disease.','Failure or loss of airway protection requires escalation.'],[['CPAP','Continuous distending pressure'],['Bilevel','Additional inspiratory assistance'],['Parallel care','Cardiac and hemodynamic treatment']],[NS],style='clinical_scenario')
q('Which is the best principle for preventing oxygen-related harm in an acutely ill adult?', 'Prescribe a target saturation range and titrate with reassessment rather than giving unlimited oxygen indefinitely',[
 ('Use the highest possible concentration for all patients after stabilization','Unnecessary hyperoxia is not a universal treatment goal.'),('Avoid oxygen in every patient at risk of hypercapnia','These patients still need controlled treatment of hypoxemia.'),('Treat the pulse-oximeter value without checking a poor signal','Measurement quality and clinical context matter.')],
 'Oxygen is a titratable treatment', '**Specify a target appropriate to the clinical syndrome.**',['Hypercapnia-risk patients commonly need 88–92% initially.','Other acute conditions may have different targets under the relevant guidance.'], '**Check response and reduce excess exposure when safe.**',['Use blood gases when ventilation or oximetry interpretation is uncertain.','Treat the underlying disease rather than only correcting a display value.'],[['Prescription','Target range'],['Delivery','Suitable device and flow'],['Review','Clinical status, saturation and gases']],[OX])
